#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int candies[4], sum = 0;
    for (int &candy : candies) {
        cin >> candy;
        sum += candy;
    }

    if (sum % 2 != 0) {
        cout << "NO";
        return 0;
    }

    for (int mask = 0; mask < (1 << 4); ++mask) {
        int subsetSum = 0;
        for (int i = 0; i < 4; ++i) {
            if (mask & (1 << i)) subsetSum += candies[i];
        }
        if (subsetSum == sum / 2) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

